namespace DeskBloom {
  internal static class AppearanceTests {
    private static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    private static IEnumerable<T> Children<T>(DependencyObject root)where T:DependencyObject {for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);var match=child as T;if(match!=null)yield return match;foreach(var next in Children<T>(child))yield return next;}}
    private static void Click(Button button){button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    private static void HiddenDialog(Window dialog,Action action){dialog.Opacity=0;dialog.ShowActivated=false;dialog.Loaded+=delegate {dialog.Dispatcher.BeginInvoke(DispatcherPriority.Background,new Action(delegate {try{action();}catch{dialog.Close();throw;}}));};dialog.ShowDialog();}
    private static void Pump(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=delegate {timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
    internal static void Run(MainWindow main,string directory,List<string> log){Assert(Appearance.Colors.Length==30&&Appearance.Colors.Distinct().Count()==30,"30 distinct accent/text colors");Assert(Appearance.Backgrounds.Length==30&&Appearance.Backgrounds.Distinct().Count()==30,"30 distinct backgrounds");for(int i=0;i<15;i++){var image=Appearance.Glyph(i,Brushes.White) as DrawingImage;Assert(image!=null&&image.IsFrozen&&image.Width==24&&image.Height==24,"bounded frozen vector icon "+i);}
      var group=main.Data.State.Groups[0];var other=main.Data.State.Groups[1];string unchanged=Appearance.Key(other),path=group.FolderPath;IntPtr handle=new WindowInteropHelper(main.GroupWindows.First(w=>w.Title.EndsWith(group.Name))).Handle;var originalCard=main.Cards.Single(c=>c.Data==group);int scans=originalCard.ScanCount;
      var appearance=new AppearanceWindow(main,group);HiddenDialog(appearance,delegate {var swatches=Children<Button>(appearance).Where(b=>AutomationProperties.GetName(b).StartsWith(L.T("Цвет")+" ")).ToArray();Assert(swatches.Length==60,"two independent 30-color palettes");Click(swatches[29]);Click(swatches[30+25]);var icon=Children<Button>(appearance).Single(b=>AutomationProperties.GetName(b)==Appearance.IconNamesRu[7]);Click(icon);Ui.Render((FrameworkElement)appearance.Content,Path.Combine(directory,"appearance-dialog.png"));Click(Children<Button>(appearance).Single(b=>AutomationProperties.GetName(b)==L.T("Сохранить")));});Pump(230);Assert(group.Color==29&&group.BackgroundColor==25&&group.Icon==7,"palette and icon Apply");Assert(Appearance.Key(other)==unchanged&&group.FolderPath==path,"appearance is per group and never moves files");Assert(main.GroupWindows.Any(w=>new WindowInteropHelper(w).Handle==handle),"appearance preserves native window handle");
      Assert(ReferenceEquals(originalCard,main.Cards.Single(c=>c.Data==group))&&originalCard.ScanCount==scans,"changing appearance reuses the card and never rescans files");group.Open=true;main.RenderCurrent(false);Pump(160);var fileNames=Directory.GetFileSystemEntries(group.FolderPath).Where(p=>!PortableLayouts.IsControlEntry(p)).Select(Path.GetFileName).ToArray();var fileLabels=Children<TextBlock>(originalCard).Where(t=>fileNames.Contains(t.Text)).ToArray();Assert(fileLabels.Length>0&&fileLabels.All(t=>t.Foreground==Appearance.BodyInk(group)),"light background keeps file labels readable");group.BackgroundColor=0;main.RenderCurrent(false);Pump(100);fileLabels=Children<TextBlock>(originalCard).Where(t=>fileNames.Contains(t.Text)).ToArray();Assert(fileLabels.Length>0&&fileLabels.All(t=>t.Foreground==Appearance.BodyInk(group)),"live dark background refreshes text contrast");group.Open=false;main.RenderCurrent(false);Assert(!Children<FileViewport>(originalCard).Any(),"collapse releases the complete content tree");group.Open=true;main.RenderCurrent(false);Pump(100);Assert(Children<FileViewport>(originalCard).Single().IsHitTestVisible,"external reopen restores interactive content");group.Open=false;main.RenderCurrent(false);
      var rename=new RenameWindow(main,group);HiddenDialog(rename,delegate {rename.Editor.SelectAll();rename.Editor.Selection.Text="Styled title";TextPointer start=rename.Editor.Document.ContentStart.GetNextInsertionPosition(LogicalDirection.Forward);rename.Editor.Selection.Select(start,start.GetPositionAtOffset(6));rename.Editor.Selection.ApplyPropertyValue(TextElement.ForegroundProperty,Ui.Brush(Appearance.Colors[4]));rename.Editor.Selection.ApplyPropertyValue(TextElement.FontWeightProperty,FontWeights.Bold);rename.Editor.Selection.ApplyPropertyValue(TextElement.FontStyleProperty,FontStyles.Italic);rename.Editor.Selection.ApplyPropertyValue(Inline.TextDecorationsProperty,TextDecorations.Underline);var parts=RenameWindow.ReadParts(rename.Editor);Assert(Appearance.Plain(parts)=="Styled title"&&parts[0].Text=="Styled"&&parts[0].Color==4&&parts[0].Bold&&parts[0].Italic&&parts[0].Underline,"selected word formatting");Assert(parts.Skip(1).All(p=>!p.Bold&&!p.Italic&&!p.Underline&&!p.Color.HasValue),"unselected text unchanged");Ui.Render((FrameworkElement)rename.Content,Path.Combine(directory,"rename-dialog.png"));Click(Children<Button>(rename).Single(b=>AutomationProperties.GetName(b)==L.T("Сохранить")));});Pump(250);Assert(group.Name=="Styled title"&&Directory.Exists(group.FolderPath)&&group.TitleParts.Count>=2,"styled rename physically renames folder");var reloaded=new Store(main.Data.Root,main.Data.GroupsRoot,main.Data.Desktop);var saved=reloaded.State.Groups.Single(g=>g.Id==group.Id);Assert(Appearance.Key(saved)==Appearance.Key(group)&&Appearance.Plain(saved.TitleParts)==saved.Name,"appearance and rich title survive restart");var document=PortableLayouts.Read(PortableLayouts.DocumentPath(group));Assert(Appearance.Key(document.Group)==Appearance.Key(group),".groups document preserves appearance and formatting");
      var editor=RenameWindow.CreateEditor(saved);editor.SelectAll();editor.Selection.ClearAllProperties();Assert(RenameWindow.ReadParts(editor).All(p=>!p.Bold&&!p.Italic&&!p.Underline&&!p.Color.HasValue),"reset clears selected formatting");Assert(!RenameWindow.ValidName("bad/name")&&!RenameWindow.ValidName("CON")&&!RenameWindow.ValidName("..")&&!RenameWindow.ValidName(new string('x',101))&&RenameWindow.ValidName("Название группы"),"Windows-safe plain title validation");
      var controls=new RenameWindow(main,group);HiddenDialog(controls,delegate {controls.Editor.SelectAll();controls.Editor.Selection.Text="Button test";var start=controls.Editor.Document.ContentStart.GetNextInsertionPosition(LogicalDirection.Forward);controls.Editor.Selection.Select(start,start.GetPositionAtOffset(6));foreach(string label in new[]{"Жирный","Курсив","Подчёркнутый"})Click(Children<Button>(controls).Single(b=>AutomationProperties.GetName(b)==L.T(label)));Click(Children<Button>(controls).Where(b=>AutomationProperties.GetName(b).StartsWith(L.T("Цвет")+" ")).ElementAt(8));var styled=RenameWindow.ReadParts(controls.Editor);Assert(styled[0].Text=="Button"&&styled[0].Bold&&styled[0].Italic&&styled[0].Underline&&styled[0].Color==8,"actual formatting buttons target selection");var text=new TextBlock();Appearance.ApplyTitle(text,new GroupData {Name="Button test",TitleParts=styled});Assert(!Ui.IsButtonSource(text.Inlines.FirstInline,text),"formatted Run clicks safely reach group header");Click(Children<Button>(controls).Single(b=>AutomationProperties.GetName(b)==L.T("Сбросить форматирование")));Assert(RenameWindow.ReadParts(controls.Editor).All(p=>!p.Bold&&!p.Italic&&!p.Underline&&!p.Color.HasValue),"actual reset button");Click(Children<Button>(controls).Single(b=>AutomationProperties.GetName(b)==L.T("Отмена")));});
      string picture=Path.Combine(directory,"own-icon.png");var bitmap=BitmapSource.Create(12,240,96,96,PixelFormats.Bgra32,null,new byte[12*240*4],48);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(picture))encoder.Save(stream);GroupAssets.SetIcon(main.Data,group,picture);main.Data.Save();string asset=GroupAssets.IconPath(main.Data,group);var custom=(BitmapSource)Appearance.Icon(main.Data,group);Assert(File.Exists(picture)&&custom.PixelWidth<=96&&custom.PixelHeight<=96&&custom.PixelHeight==96,"custom image bounded without moving original");Assert(PortableLayouts.IsControlEntry(Path.GetDirectoryName(asset)),"owned icon folder excluded from file grid");Assert(GroupAssets.IconPath(main.Data,new GroupData {IconImage="../private.png"})==null,"descriptor cannot load arbitrary image paths");main.RenderCurrent(false);Pump(450);var card=main.Cards.Single(c=>c.Data==group);int expected=Directory.GetFileSystemEntries(group.FolderPath).Count(p=>!PortableLayouts.IsControlEntry(p));Assert(card.FileCount==expected,"asset directory never appears as group content");string oldAsset=asset;Migration.MoveGroup(main.Data,group,Path.GetDirectoryName(group.FolderPath),"Portable icon");main.RenderCurrent(false);Pump(250);Assert(!File.Exists(oldAsset)&&File.Exists(GroupAssets.IconPath(main.Data,group)),"custom image moves with ordinary group folder");
      var cancel=new AppearanceWindow(main,group);string before=Appearance.Key(group);HiddenDialog(cancel,delegate {Click(Children<Button>(cancel).First(b=>AutomationProperties.GetName(b).StartsWith(L.T("Цвет")+" ")));Click(Children<Button>(cancel).Single(b=>AutomationProperties.GetName(b)==L.T("Отмена")));});Assert(Appearance.Key(group)==before,"Cancel discards draft colors");
      log.Add("PASS: two independent 30-color palettes, all 15 frozen vector icons, per-group Apply/Cancel, native window reuse, selected-word color/bold/italic/underline, reset and valid names, physical styled rename, state/.groups persistence, custom icon scaling/portability and metadata exclusion.");
    }
  }
